import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"占位符参考","description":"","frontmatter":{},"headers":[],"relativePath":"modules/cooking/placeholders.md","filePath":"modules/cooking/placeholders.md","lastUpdated":0}`),a={name:`modules/cooking/placeholders.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="占位符参考" tabindex="-1">占位符参考 <a class="header-anchor" href="#占位符参考" aria-label="Permalink to “占位符参考”">​</a></h1><h2 id="placeholderapi-占位符" tabindex="-1">PlaceholderAPI 占位符 <a class="header-anchor" href="#placeholderapi-占位符" aria-label="Permalink to “PlaceholderAPI 占位符”">​</a></h2><p>扩展标识符：<code>emakicooking</code></p><p>安装 PlaceholderAPI 后，EmakiCooking 会自动注册以下占位符。</p><table tabindex="0"><thead><tr><th>占位符</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>%emakicooking_recipe_count%</code></td><td>所有烹饪站配方总数。</td><td><code>42</code></td></tr><tr><td><code>%emakicooking_recipe_count_chopping_board%</code></td><td>砧板配方数量。</td><td><code>8</code></td></tr><tr><td><code>%emakicooking_recipe_count_wok%</code></td><td>炒锅配方数量。</td><td><code>12</code></td></tr><tr><td><code>%emakicooking_recipe_count_grinder%</code></td><td>研磨机配方数量。</td><td><code>5</code></td></tr><tr><td><code>%emakicooking_recipe_count_steamer%</code></td><td>蒸锅配方数量。</td><td><code>6</code></td></tr><tr><td><code>%emakicooking_recipe_count_oven%</code></td><td>烤箱配方数量。</td><td><code>4</code></td></tr><tr><td><code>%emakicooking_recipe_count_juicer%</code></td><td>榨汁机配方数量。</td><td><code>3</code></td></tr><tr><td><code>%emakicooking_recipe_count_fermentation_barrel%</code></td><td>发酵桶配方数量。</td><td><code>4</code></td></tr></tbody></table><h3 id="营养占位符" tabindex="-1">营养占位符 <a class="header-anchor" href="#营养占位符" aria-label="Permalink to “营养占位符”">​</a></h3><p>营养相关占位符同样使用 <code>emakicooking</code> 标识符。营养玩法见 <a href="./nutrition.html">营养系统</a>。</p><table tabindex="0"><thead><tr><th>占位符</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>%emakicooking_nutrition_&lt;type&gt;%</code></td><td>玩家某营养类型当前值。</td><td><code>60</code></td></tr><tr><td><code>%emakicooking_nutrition_&lt;type&gt;_max%</code></td><td>营养类型上限。</td><td><code>100</code></td></tr><tr><td><code>%emakicooking_nutrition_&lt;type&gt;_min%</code></td><td>营养类型下限。</td><td><code>0</code></td></tr><tr><td><code>%emakicooking_nutrition_combo_count_&lt;ruleId&gt;%</code></td><td>指定组合阈值规则当前达标的营养类型数量。</td><td><code>3</code></td></tr></tbody></table><p><code>&lt;type&gt;</code> 为营养类型 id（如 <code>fruit</code>、<code>protein</code>），<code>&lt;ruleId&gt;</code> 为组合阈值规则 id。营养占位符依赖玩家状态，需要在线玩家上下文。</p><h3 id="工位运行态占位符" tabindex="-1">工位运行态占位符 <a class="header-anchor" href="#工位运行态占位符" aria-label="Permalink to “工位运行态占位符”">​</a></h3><p>工位运行态占位符用于读取玩家当前关联工位的实时状态，同样使用 <code>emakicooking</code> 标识符。有两种写法：</p><ul><li><code>%emakicooking_station_&lt;字段&gt;%</code>：自动取玩家当前关联的工位。</li><li><code>%emakicooking_station_&lt;工位类型&gt;_&lt;字段&gt;%</code>：仅当玩家关联工位与指定类型一致时才返回，否则返回空串。工位类型为文件夹名（<code>chopping_board</code>、<code>wok</code>、<code>grinder</code>、<code>steamer</code>、<code>oven</code>、<code>juicer</code>、<code>fermentation_barrel</code>）。</li></ul><p>工位关联方式：优先取玩家<strong>最近一次交互的工位</strong>（需玩家仍在同一世界且距离不超过内置上限），其次取玩家正打开的工位 GUI 会话（蒸锅 / 烤炉 / 榨汁机 / 发酵桶）。玩家无关联工位或工位为空态时返回空串。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>type</code></td><td>工位类型（文件夹名）。</td><td><code>chopping_board</code></td></tr><tr><td><code>type_name</code></td><td>工位显示名。</td><td><code>砧板</code></td></tr><tr><td><code>world</code></td><td>工位所在世界名。</td><td><code>world</code></td></tr><tr><td><code>x</code></td><td>工作方块 X 坐标。</td><td><code>100</code></td></tr><tr><td><code>y</code></td><td>工作方块 Y 坐标。</td><td><code>64</code></td></tr><tr><td><code>z</code></td><td>工作方块 Z 坐标。</td><td><code>-200</code></td></tr><tr><td><code>location</code></td><td>工位坐标合并串 <code>世界,x,y,z</code>，便于整串匹配。</td><td><code>world,100,64,-200</code></td></tr><tr><td><code>block</code></td><td>工作方块 id（自定义方块 id 或原版 Material 名）。</td><td><code>minecraft:oak_log</code></td></tr><tr><td><code>heat_block</code></td><td>热源方块 id（工作方块下方，无热源为空）。</td><td><code>minecraft:furnace</code></td></tr><tr><td><code>burning</code></td><td>热源是否正在燃烧。</td><td><code>true</code></td></tr><tr><td><code>burning_seconds</code></td><td>热源剩余燃烧秒数。</td><td><code>40</code></td></tr><tr><td><code>heat</code></td><td>热度（烤炉）/ 火力等级（炒锅）。</td><td><code>60</code></td></tr><tr><td><code>moisture</code></td><td>水分（蒸锅）。</td><td><code>80</code></td></tr><tr><td><code>steam</code></td><td>蒸汽（蒸锅）。</td><td><code>30</code></td></tr><tr><td><code>input</code></td><td>主输入物品纯文本名。</td><td><code>苹果</code></td></tr><tr><td><code>input_source</code></td><td>主输入物品来源简写。</td><td><code>minecraft-apple</code></td></tr><tr><td><code>input_amount</code></td><td>主输入物品数量。</td><td><code>16</code></td></tr><tr><td><code>ingredient_count</code></td><td>输入物品种类数。</td><td><code>3</code></td></tr><tr><td><code>recipe</code></td><td>当前匹配 / 进行中的配方显示名。</td><td><code>苹果汁</code></td></tr><tr><td><code>recipe_id</code></td><td>当前配方 id。</td><td><code>apple_juice</code></td></tr><tr><td><code>progress</code></td><td>进度当前值。</td><td><code>2</code></td></tr><tr><td><code>progress_target</code></td><td>进度目标值。</td><td><code>5</code></td></tr><tr><td><code>progress_percent</code></td><td>进度百分比（保留 1 位小数）。</td><td><code>40.0</code></td></tr><tr><td><code>completed</code></td><td>是否已完成（可收取）。</td><td><code>false</code></td></tr><tr><td><code>fluid</code></td><td>流体名（榨汁机）。</td><td><code>苹果汁</code></td></tr><tr><td><code>fluid_amount</code></td><td>流体毫升量（榨汁机）。</td><td><code>500</code></td></tr><tr><td><code>player</code></td><td>操作 / 查看玩家名。</td><td><code>Steve</code></td></tr></tbody></table><p>不适用于当前工位的字段返回空串或 0（例如砧板没有热源，<code>heat_block</code> 为空、<code>burning</code> 为 <code>false</code>）。</p><h4 id="条件配方玩法示例" tabindex="-1">条件配方玩法示例 <a class="header-anchor" href="#条件配方玩法示例" aria-label="Permalink to “条件配方玩法示例”">​</a></h4><p>配合配方的 <code>availability_condition</code> / <code>condition</code>，可以用工位坐标区分同种工位的具体个体。例如摆放两个相同砧板，只让特定坐标的砧板能完成某配方（坐标合并串含逗号，作字符串比较需加引号）：</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">availability_condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">all_of</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  entries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%emakicooking_station_location% == &quot;world,100,64,-200&quot;&#39;</span></span></code></pre></div><p>也可以只用单个坐标字段匹配：</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">availability_condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">all_of</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  entries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%emakicooking_station_x% == 100&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%emakicooking_station_z% == -200&#39;</span></span></code></pre></div><p>条件块的完整语法（<code>type</code> / <code>entries</code> / <code>on_fail</code> 等）见 <a href="./../corelib/condition.html">条件系统</a>。</p><h3 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to “使用示例”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;总配方数: &lt;white&gt;%emakicooking_recipe_count%&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;炒锅配方: &lt;white&gt;%emakicooking_recipe_count_wok%&#39;</span></span></code></pre></div><h2 id="内部模板变量" tabindex="-1">内部模板变量 <a class="header-anchor" href="#内部模板变量" aria-label="Permalink to “内部模板变量”">​</a></h2><p>以下变量可用于配方的 <code>structured_presentation</code>（名称与 Lore 操作模板）中，使用 <code>%variable%</code> 格式。</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>%recipe_id%</code></td><td>配方 ID。</td><td><code>grilled_steak</code></td></tr><tr><td><code>%recipe_name%</code></td><td>配方显示名。</td><td><code>烤牛排</code></td></tr><tr><td><code>%station_type%</code></td><td>工位类型（文件夹名）。</td><td><code>oven</code></td></tr><tr><td><code>%phase%</code></td><td>当前烹饪阶段。</td><td><code>cooking</code></td></tr><tr><td><code>%output_source%</code></td><td>产出物品来源简写。</td><td><code>minecraft-cooked_beef</code></td></tr><tr><td><code>%output_amount%</code></td><td>产出数量。</td><td><code>1</code></td></tr><tr><td><code>%output_chance%</code></td><td>产出概率。</td><td><code>100%</code></td></tr><tr><td><code>%output_amount_min%</code></td><td>产出数量范围最小值。仅在结果写了 <code>amount_range</code> 时存在。</td><td><code>1</code></td></tr><tr><td><code>%output_amount_max%</code></td><td>产出数量范围最大值。仅在结果写了 <code>amount_range</code> 时存在。</td><td><code>3</code></td></tr></tbody></table><p><code>%output_source%</code> 使用 CoreLib ItemSource 简写形式，例如 <code>minecraft-cooked_beef</code>。</p><h3 id="模板示例" tabindex="-1">模板示例 <a class="header-anchor" href="#模板示例" aria-label="Permalink to “模板示例”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">structured_presentation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  lore_actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;append&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;配方: &lt;white&gt;%recipe_name%&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;工位: &lt;white&gt;%station_type%&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;产出: &lt;white&gt;%output_amount%x %output_source%&quot;</span></span></code></pre></div><h2 id="动作上下文变量" tabindex="-1">动作上下文变量 <a class="header-anchor" href="#动作上下文变量" aria-label="Permalink to “动作上下文变量”">​</a></h2><p>烹饪奖励动作（CookingRewardService）触发时，以下变量会注入到 Action 上下文中：</p><table tabindex="0"><thead><tr><th>变量</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>%player%</code></td><td>玩家名称。</td><td><code>Steve</code></td></tr><tr><td><code>%player_uuid%</code></td><td>玩家 UUID。</td><td><code>00000000-0000-0000-0000-000000000000</code></td></tr><tr><td><code>%world%</code></td><td>世界名称。</td><td><code>world</code></td></tr><tr><td><code>%x%</code></td><td>工位方块 X 坐标。</td><td><code>100</code></td></tr><tr><td><code>%y%</code></td><td>工位方块 Y 坐标。</td><td><code>64</code></td></tr><tr><td><code>%z%</code></td><td>工位方块 Z 坐标。</td><td><code>-200</code></td></tr><tr><td><code>%recipe_id%</code></td><td>当前配方 ID。</td><td><code>grilled_steak</code></td></tr><tr><td><code>%recipe_name%</code></td><td>配方显示名。</td><td><code>烤牛排</code></td></tr><tr><td><code>%station_type%</code></td><td>工位类型（文件夹名）。</td><td><code>oven</code></td></tr><tr><td><code>%cooking_recipe_id%</code></td><td><code>%recipe_id%</code> 的带前缀写法。</td><td><code>grilled_steak</code></td></tr><tr><td><code>%cooking_recipe_name%</code></td><td><code>%recipe_name%</code> 的带前缀写法。</td><td><code>烤牛排</code></td></tr><tr><td><code>%cooking_station_type%</code></td><td><code>%station_type%</code> 的带前缀写法。</td><td><code>oven</code></td></tr><tr><td><code>%input_count%</code></td><td>本次参与结算的输入种类数。</td><td><code>3</code></td></tr></tbody></table><p>部分工位在完成结算时还会额外注入自己的变量：</p><table tabindex="0"><thead><tr><th>变量</th><th>注入方</th><th>说明</th></tr></thead><tbody><tr><td><code>%outcome%</code></td><td>炒锅</td><td>命中的结果分支名。</td></tr><tr><td><code>%slot_index%</code></td><td>烤炉、蒸锅、榨汁机</td><td>本次结算的槽位索引。</td></tr></tbody></table><p>产物级模板（<code>structured_presentation</code>）在上述变量基础上再追加 <code>%phase%</code>、<code>%output_source%</code>、<code>%output_amount%</code>、<code>%output_chance%</code>、<code>%output_amount_min%</code>、<code>%output_amount_max%</code>。</p><h3 id="动作示例" tabindex="-1">动作示例 <a class="header-anchor" href="#动作示例" aria-label="Permalink to “动作示例”">​</a></h3><p>配方结果分支中的 <code>actions</code> 是 CoreLib 动作字符串列表：</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;send_message text=&quot;&lt;green&gt;%player% 在 %station_type% 完成了 %recipe_id% 的烹饪！&lt;/green&gt;&quot;&#39;</span></span></code></pre></div><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to “说明”">​</a></h2><ul><li>PAPI 占位符不依赖玩家状态，<code>recipe_count</code> 系列为全局值，适合用于管理面板或计分板。</li><li>CoreLib 的内置上下文变量（<code>%player_name%</code>、<code>%player_uuid%</code> 等）同样可用。</li></ul>`,40)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};